<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '../stores/auth'
import { navigation } from '../navigation'
import { api, errorText } from '../api/http'
import NavIcon from '../components/NavIcon.vue'
const auth=useAuthStore(), route=useRoute(), router=useRouter()
const collapsed=ref(false), quick=ref(''), help=ref(false), passwordDialog=ref(false), busy=ref(false), currentPassword=ref(''), newPassword=ref(''), passwordError=ref('')
const navigationMedia = window.matchMedia('(max-width: 1100px)')
const narrowNavigation = ref(navigationMedia.matches), mobileNavigation = ref(false)
function navigationResize(event: MediaQueryListEvent) { narrowNavigation.value = event.matches; mobileNavigation.value = false }
function toggleNavigation() { if (narrowNavigation.value) mobileNavigation.value = !mobileNavigation.value; else collapsed.value = !collapsed.value }
navigationMedia.addEventListener('change', navigationResize)
onBeforeUnmount(() => navigationMedia.removeEventListener('change', navigationResize))
watch(() => route.path, () => { mobileNavigation.value = false })
const menu=computed(()=>navigation.map(group=>({...group,items:group.items.filter(item=>auth.can(item.permission))})).filter(group=>group.items.length))
const currentGroup=computed(()=>navigation.find(g=>g.items.some(item=>route.path.startsWith(item.path)))?.group||'系统')
async function account(command:string){if(command==='password'){passwordError.value='';passwordDialog.value=true}else if(command==='logout'){busy.value=true;try{await auth.logout();await router.replace('/login')}catch(e){ElMessage.error(errorText(e))}finally{busy.value=false;await router.replace('/login')}}}
async function changePassword(){busy.value=true;passwordError.value='';try{await api.put('/auth/password',{currentPassword:currentPassword.value,newPassword:newPassword.value});auth.clear();passwordDialog.value=false;await router.replace('/login');ElMessage.success('密码已修改，请重新登录')}catch(e){passwordError.value=errorText(e)}finally{busy.value=false;currentPassword.value='';newPassword.value=''}}
</script>
<template><div class="app-frame" :class="{collapsed, 'mobile-nav-open': mobileNavigation, 'ai-route': route.path === '/ai-analysis'}" @keydown.esc="mobileNavigation=false">
  <button v-if="mobileNavigation" class="navigation-scrim" aria-label="关闭导航菜单" @click="mobileNavigation=false"/>
  <aside class="sidebar"><router-link class="brand" to="/"><span class="brand-mark">M</span><span class="brand-text">轻量制造</span></router-link><nav id="main-navigation" aria-label="主导航"><section v-for="group in menu" :key="group.group" class="nav-group"><div class="nav-group-title">{{group.group}}</div><router-link v-for="item in group.items" :key="item.path" :to="item.path" :title="item.label" class="nav-item" :class="{active:route.path.startsWith(item.path)}"><NavIcon :name="item.icon"/><span>{{item.label}}</span></router-link></section></nav></aside>
  <div class="app-main"><header class="topbar"><button class="icon-button menu-toggle" :aria-label="(narrowNavigation ? !mobileNavigation : collapsed) ? '展开菜单' : '折叠菜单'" :aria-expanded="narrowNavigation ? mobileNavigation : !collapsed" aria-controls="main-navigation" @click="toggleNavigation"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16"/></svg></button><el-breadcrumb v-if="route.path !== '/ai-analysis'" separator="/"><el-breadcrumb-item>{{currentGroup}}</el-breadcrumb-item><el-breadcrumb-item>{{route.meta.title}}</el-breadcrumb-item><el-breadcrumb-item v-if="route.meta.detail">详情</el-breadcrumb-item></el-breadcrumb><div class="toolbar-right"><el-select v-model="quick" filterable clearable placeholder="搜索功能" class="quick-search" aria-label="搜索功能" @change="(value:string)=>{if(value){router.push(value);quick=''}}"><el-option v-for="item in menu.flatMap(g=>g.items)" :key="item.path" :value="item.path" :label="item.label"/></el-select><el-popover placement="bottom-end" :width="260" trigger="click"><template #reference><button class="icon-button" aria-label="业务待办"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4"/></svg></button></template><strong>业务待办</strong><p class="muted">查看首页概览中的实时待办，进入单据继续下一步操作。</p><el-button v-if="auth.can('workbench:read')" type="primary" text @click="router.push('/workbench')">打开首页概览</el-button></el-popover><button class="icon-button" aria-label="使用帮助" @click="help=true">?</button><el-dropdown @command="account"><button class="account-button" :disabled="busy"><span class="avatar">{{auth.user?.displayName.slice(0,1)}}</span><span>{{auth.user?.displayName}}</span><span class="muted">⌄</span></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="password">账号设置 · 修改密码</el-dropdown-item><el-dropdown-item divided command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
  <main class="main-content"><router-view :key="route.path"/></main></div>
  <el-dialog v-model="help" title="六步完成一次电脑组装" width="540px"><p>采购零部件 → 全量收货 → 确认整机工单 → 按 BOM 领料 → 组装报工与整机入库 → 销售发货。</p><el-alert type="info" :closable="false" title="报工不会增加整机库存。请打开关联的待执行成品入库单，执行入库后工单才完成。"/><p class="muted">数量只接受整数；确认后的单据不能修改或反冲。操作失败可用页面显示的追踪号排查。</p></el-dialog>
  <el-dialog v-model="passwordDialog" title="修改登录密码" width="440px" @closed="currentPassword='';newPassword='' "><el-alert v-if="passwordError" :title="passwordError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="changePassword"><el-form-item label="当前密码"><el-input v-model="currentPassword" type="password" show-password autocomplete="current-password" aria-label="当前密码"/></el-form-item><el-form-item label="新密码（12～64字符，UTF-8最多72字节）"><el-input v-model="newPassword" type="password" show-password autocomplete="new-password" aria-label="新密码"/></el-form-item><el-button native-type="submit" type="primary" :loading="busy">修改并重新登录</el-button></el-form></el-dialog>
</div></template>
